begin;
select set_config('test.rf_old',gen_random_uuid()::text,true),set_config('test.rf_new',gen_random_uuid()::text,true),set_config('test.rf_other',gen_random_uuid()::text,true),set_config('test.rf_owner',(select uid::text from politeshik_private.super_admins limit 1),true);
select set_config('test.rf_name',(select name from politeshik_private.faculty_directory d where not exists(select 1 from politeshik_private.faculty_claims c where c.faculty_id=d.id and c.status='approved')order by id limit 1),true);
insert into auth.users(id,email,email_confirmed_at,aud,role)values(current_setting('test.rf_old')::uuid,'re-register-'||current_setting('test.rf_new')||'@example.invalid',now(),'authenticated','authenticated'),(current_setting('test.rf_other')::uuid,'other-'||current_setting('test.rf_other')||'@example.invalid',now(),'authenticated','authenticated');
update politeshik_private.faculty_directory set registration_email='re-register-'||current_setting('test.rf_new')||'@example.invalid'where name=current_setting('test.rf_name');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_old'),'role','authenticated')::text,true);
select public.faculty_request(current_setting('test.rf_name'));
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_owner'),'role','authenticated')::text,true);
select public.faculty_decide(current_setting('test.rf_old')::uuid,true);
reset role;
select set_config('request.jwt.claims','{}',true);
update public.members set status='banned'where uid=current_setting('test.rf_old')::uuid;
update politeshik_private.faculty_claims set status='rejected'where uid=current_setting('test.rf_old')::uuid;
update auth.users set email='archived-'||id::text||'@example.invalid'where id=current_setting('test.rf_old')::uuid;
do $$begin assert not exists(select 1 from politeshik_private.faculty_claims where uid=current_setting('test.rf_old')::uuid and status='approved'),'Released faculty still occupied';assert exists(select 1 from public.docs where path='profiles/'||current_setting('test.rf_old')),'Release destroyed profile history';end $$;
insert into auth.users(id,email,aud,role)values(current_setting('test.rf_new')::uuid,'re-register-'||current_setting('test.rf_new')||'@example.invalid','authenticated','authenticated');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_new'),'role','authenticated')::text,true);
do $$declare denied boolean:=false;begin begin perform public.faculty_request(current_setting('test.rf_name'));exception when insufficient_privilege then denied:=true;end;assert denied,'Unverified reserved email granted access';end $$;
reset role;
update auth.users set email_confirmed_at=now()where id=current_setting('test.rf_new')::uuid;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_other'),'role','authenticated')::text,true);
do $$declare denied boolean:=false;begin begin perform public.faculty_request(current_setting('test.rf_name'));exception when insufficient_privilege then denied:=true;end;assert denied,'Other email claimed reserved identity';end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_new'),'role','authenticated')::text,true);
do $$declare denied boolean:=false;begin
 assert public.faculty_request(current_setting('test.rf_name'));assert public.faculty_context()->>'status'='pending','Reservation bypassed owner approval';
 begin perform public.faculty_request('Васильев Сергей Юрьевич');exception when insufficient_privilege then denied:=true;end;assert denied,'Reserved email can claim another teacher';denied:=false;
 begin perform public.faculty_decide(auth.uid(),true);exception when insufficient_privilege then denied:=true;end;assert denied,'Teacher self-approved';
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_owner'),'role','authenticated')::text,true);
select public.faculty_decide(current_setting('test.rf_new')::uuid,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rf_new'),'role','authenticated')::text,true);
do $$declare ctx jsonb:=public.faculty_context();begin assert ctx->>'active'='true','New account failed activation';assert ctx->>'name'=current_setting('test.rf_name'),'Wrong teacher bound';assert not(ctx?'registration_email'),'Reserved email leaked to client';end $$;
reset role;
rollback;
